'use strict';
// A route still occupies one output/input pair. Its segments describe serial cables.
function cableSegments(edge){return edge.segments?edge.segments.map(s=>({...s})):[{id:'base',length:edge.length,note:''}]}
function cableLengthText(value){return Number(Number(value).toFixed(3)).toString()+'m'}
function cableSegmentTotal(segments){return Number(segments.reduce((sum,s)=>sum+s.length,0).toFixed(6))}
function validateCableSegments(edge){if(edge.segments===undefined)return;let ss=edge.segments,ids=new Set();if(!Array.isArray(ss)||!ss.length||ss.length>12)throw Error('ケーブルは1〜12区間で設定してください');for(let s of ss){if(!s||typeof s.id!=='string'||!/^[a-zA-Z0-9_-]{1,100}$/.test(s.id)||ids.has(s.id)||!Number.isFinite(s.length)||s.length<=0||s.length>1000||s.note!==undefined&&(typeof s.note!=='string'||s.note.length>120))throw Error('区間の長さ・コメントが不正です');ids.add(s.id)}if(!Number.isFinite(edge.length)||Math.abs(cableSegmentTotal(ss)-edge.length)>.000001||edge.length>1000)throw Error('区間の合計は1000m以下で、ケーブルの全長と一致させてください')}
function cableSegmentType(edge,index){if(!index)return edge.type;return({XLR_TRS:'TRS',TRS_XLR:'XLR',XLR_MIC_TRS:'TRS',RCA_TS:'TS',HDMI_MICRO:'HDMI'})[edge.type]||edge.type}
function cableInventory(edges){return edges.flatMap(edge=>cableSegments(edge).map((segment,index)=>({edge,segment,index,type:cableSegmentType(edge,index)})))}
function cableRoute(a,b,index=0){let points=[a],d;if(b.x<a.x){let lane=Math.max(a.x,b.x)+75+(index%4)*14;points.push({x:lane,y:a.y},{x:lane,y:b.y+45},{x:b.x-28,y:b.y+45},{x:b.x-28,y:b.y},b);d=`M${a.x},${a.y} H${lane} V${b.y+45} H${b.x-28} V${b.y} H${b.x}`}else{let mid=(a.x+b.x)/2+(index%2)*12;d=`M${a.x},${a.y} C${mid},${a.y} ${mid},${b.y} ${b.x},${b.y}`;for(let i=1;i<=64;i++){let t=i/64,u=1-t;points.push({x:u*u*u*a.x+3*u*u*t*mid+3*u*t*t*mid+t*t*t*b.x,y:u*u*u*a.y+3*u*u*t*a.y+3*u*t*t*b.y+t*t*t*b.y})}}let distances=[0];for(let i=1;i<points.length;i++)distances.push(distances[i-1]+Math.hypot(points[i].x-points[i-1].x,points[i].y-points[i-1].y));return{d,points,distances,length:distances.at(-1)}}
function cableRoutePoint(route,fraction){let goal=route.length*Math.max(0,Math.min(1,fraction)),i=route.distances.findIndex(d=>d>=goal);if(i<=0)return route.points[0];let a=route.points[i-1],b=route.points[i],den=route.distances[i]-route.distances[i-1],t=den?(goal-route.distances[i-1])/den:0;return{x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t}}
function cableAnnotationMarkup(edge,route,options={}){let scale=options.scale||1,escape=options.escape||String,interactive=options.interactive,placed=options.placed||[],ss=cableSegments(edge),total=cableSegmentTotal(ss),sum=0,html='',bg=options.light?'#faf9f5':'#30312d',ink=options.light?'#33362d':'#f0efe9',line=options.color||'#888b7d';for(let i=0;i<ss.length;i++){let s=ss[i],p=cableRoutePoint(route,(sum+s.length/2)/total),width=(cableLengthText(s.length).length*6.2+(s.note?21:14))/scale,height=19/scale,x=p.x,y=p.y-14/scale;for(let attempt=0;attempt<12&&placed.some(r=>Math.abs(r.x-x)<(r.w+width)/2+4/scale&&Math.abs(r.y-y)<(r.h+height)/2+3/scale);attempt++)y-=23/scale;placed.push({x,y,w:width,h:height});let attr=interactive?` data-edge="${escape(edge.id)}" data-cable-section="${i}" role="button" tabindex="0" aria-label="区間${i+1} ${escape(cableLengthText(s.length))}、長さとコメントを編集"`:'';html+=`<g class="cable-length-label"${attr}><title>${escape((i?'延長 '+i:'ケーブル 1')+' · '+cableLengthText(s.length)+(s.note?' · '+s.note:''))}</title>${Math.abs(y-(p.y-14/scale))>1?`<path class="cable-label-leader" d="M${x},${y+height/2} L${p.x},${p.y}" stroke="${line}" stroke-width="${.7/scale}" opacity=".65"/>`:''}<rect x="${x-width/2}" y="${y-height/2}" width="${width}" height="${height}" rx="${3/scale}" fill="${bg}" stroke="${line}" stroke-width="${.7/scale}"/><text x="${x}" y="${y+3.7/scale}" text-anchor="middle" font-family="Arial,sans-serif" font-size="${11/scale}" fill="${ink}">${escape(cableLengthText(s.length))}${s.note?' ·':''}</text></g>`;sum+=s.length;if(i<ss.length-1){let joint=cableRoutePoint(route,sum/total);html+=`<g class="cable-junction"${interactive?` data-edge="${escape(edge.id)}" role="button" tabindex="0" aria-label="中継点 ${i+1} を編集"`:''}><title>中継点 ${i+1} · ${escape(cableLengthText(total))}（合計）</title><circle cx="${joint.x}" cy="${joint.y}" r="${5/scale}" fill="${bg}" stroke="${line}" stroke-width="${1.6/scale}"/><circle cx="${joint.x}" cy="${joint.y}" r="${1.5/scale}" fill="${line}"/></g>`}}return html}
if(typeof module!=='undefined')module.exports={cableSegments,cableLengthText,cableSegmentTotal,validateCableSegments,cableSegmentType,cableInventory,cableRoute,cableRoutePoint,cableAnnotationMarkup};
